    "content": "export type GSBadge =\n  | 'GS-1'\n  | 'GS-2'\n  | 'GS-3'\n  | 'GS-4'\n  | 'CSAT'\n  | 'Current Affairs'\n  | 'Essay'\n  | 'Optional';\n\nexport type BroadcastSource = 'youtube' | 'meet' | 'zoom' | 'hls' | 'vimeo' | 'custom';\n\nexport type BroadcastStatus = 'live' | 'scheduled' | 'completed';\n\nexport interface BroadcastClass {\n  id: string;\n  title: string;\n  subject: GSBadge;\n  faculty: string;\n  facultyDesignation?: string;\n  source: BroadcastSource;\n  streamUrl: string;\n  scheduledDate: string;\n  scheduledTime: string;\n  durationMinutes: number;\n  status: BroadcastStatus;\n  description?: string;\n  topicsCovered: string[];\n  handoutUrl?: string;\n  handoutTitle?: string;\n  thumbnail?: string;\n  viewersCount?: number;\n  meetingId?: string;\n  meetingPassword?: string;\n  chatEnabled?: boolean;\n  createdAt?: string;\n}\n\nexport interface LectureDoubt {\n  id: string;\n  user: string;\n  avatar: string;\n  query: string;\n  upvotes: number;\n  isAnswered: boolean;\n  timeAgo: string;\n  facultyReply?: string;\n  userUpvoted?: boolean;\n}\n\nexport interface LectureNote {\n  id: string;\n  timestampSeconds: number;\n  formattedTime: string;\n  text: string;\n  createdAt: string;\n}\n\nexport interface ClassHandout {\n  id: string;\n  title: string;\n  subject: GSBadge;\n  pages: number;\n  size: string;\n  downloadUrl?: string;\n  author: string;\n  summary: string;\n  keyTopics: string[];\n}\n\nexport interface ProjectFileItem {\n  path: string;\n  name: string;\n  category: 'core' | 'component' | 'data' | 'types' | 'config' | 'style' | 'docs';\n  extension: string;\n  sizeBytes: number;\n  content: string;\n}\n"
